import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { assignees, issues, statuses } from '../data/issues';

export default function IssueList() {
  const [searchParams, setSearchParams] = useSearchParams();
  const requestedStatus = searchParams.get('status') ?? 'all';
  const requestedAssignee = searchParams.get('assignee') ?? 'all';
  const status = requestedStatus === 'all' || statuses.includes(requestedStatus as (typeof statuses)[number])
    ? requestedStatus
    : 'all';
  const assignee = requestedAssignee === 'all' || assignees.includes(requestedAssignee)
    ? requestedAssignee
    : 'all';

  const updateFilters = (nextStatus: string, nextAssignee: string) => {
    const nextParams = new URLSearchParams(searchParams);
    if (nextStatus === 'all') nextParams.delete('status');
    else nextParams.set('status', nextStatus);
    if (nextAssignee === 'all') nextParams.delete('assignee');
    else nextParams.set('assignee', nextAssignee);
    setSearchParams(nextParams);
  };

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <h1>Issues</h1>
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={(nextStatus) => updateFilters(nextStatus, assignee)}
        onAssigneeChange={(nextAssignee) => updateFilters(status, nextAssignee)}
        onClear={() => updateFilters('all', 'all')}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

