import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { assignees, issues, statuses } from '../data/issues';

function readFilter(value: string | null, choices: string[]) {
  return value && choices.includes(value) ? value : 'all';
}

export default function IssueList() {
  const [searchParams, setSearchParams] = useSearchParams();
  const [status, setStatus] = useState(() => readFilter(searchParams.get('status'), statuses));
  const [assignee, setAssignee] = useState(() => readFilter(searchParams.get('assignee'), assignees));

  const updateFilters = (nextStatus: string, nextAssignee: string) => {
    setStatus(nextStatus);
    setAssignee(nextAssignee);
    const params = new URLSearchParams(searchParams);
    if (nextStatus === 'all') params.delete('status');
    else params.set('status', nextStatus);
    if (nextAssignee === 'all') params.delete('assignee');
    else params.set('assignee', nextAssignee);
    setSearchParams(params);
  };

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <h1>Issues</h1>
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={(value) => updateFilters(value, assignee)}
        onAssigneeChange={(value) => updateFilters(status, value)}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

