import { useState } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues, type Issue } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [createdIssues, setCreatedIssues] = useState<Issue[]>([]);
  const [isCreating, setIsCreating] = useState(false);
  const [title, setTitle] = useState('');
  const [titleError, setTitleError] = useState('');

  const allIssues = [...createdIssues, ...issues];
  const visible = allIssues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  function createIssue(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setTitleError('Title is required.');
      return;
    }

    setCreatedIssues((current) => [
      {
        id: Math.max(...issues.map((issue) => issue.id), ...createdIssues.map((issue) => issue.id), 0) + 1,
        title: trimmedTitle,
        description: '',
        status: 'open',
        assignee: 'Unassigned',
        tags: [],
        createdAt: new Date().toISOString().slice(0, 10),
      },
      ...current,
    ]);
    setTitle('');
    setTitleError('');
    setIsCreating(false);
  }

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" className="new-issue-button" onClick={() => setIsCreating((open) => !open)}>
          New issue
        </button>
      </div>
      {isCreating && (
        <form className="new-issue-form" onSubmit={createIssue} noValidate>
          <label htmlFor="new-issue-title">Title</label>
          <input
            id="new-issue-title"
            autoFocus
            value={title}
            onChange={(event) => {
              setTitle(event.target.value);
              if (titleError) setTitleError('');
            }}
            aria-invalid={Boolean(titleError)}
            aria-describedby={titleError ? 'new-issue-title-error' : undefined}
          />
          {titleError && <p id="new-issue-title-error" className="new-issue-error" role="alert">{titleError}</p>}
          <div className="new-issue-actions">
            <button type="submit">Create issue</button>
            <button type="button" onClick={() => { setIsCreating(false); setTitleError(''); }}>Cancel</button>
          </div>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {allIssues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

