import { useState, type FormEvent } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [creating, setCreating] = useState(false);
  const [title, setTitle] = useState('');
  const [error, setError] = useState('');
  const [, refresh] = useState(0);

  const createIssue = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setError('Title is required.');
      return;
    }

    issues.push({
      id: Math.max(0, ...issues.map((issue) => issue.id)) + 1,
      title: trimmedTitle,
      description: '',
      status: 'open',
      assignee: 'Unassigned',
      tags: [],
      createdAt: new Date().toISOString().slice(0, 10),
    });
    refresh((value) => value + 1);
    setTitle('');
    setError('');
    setCreating(false);
  };

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" className="new-issue-button" onClick={() => setCreating(true)}>
          New issue
        </button>
      </div>
      {creating && (
        <form className="new-issue-form" onSubmit={createIssue}>
          <label htmlFor="issue-title">Title</label>
          <input
            id="issue-title"
            name="title"
            type="text"
            value={title}
            onChange={(event) => {
              setTitle(event.target.value);
              if (error) setError('');
            }}
            aria-invalid={Boolean(error)}
            aria-describedby={error ? 'issue-title-error' : undefined}
            autoFocus
          />
          {error && <p className="new-issue-error" id="issue-title-error" role="alert">{error}</p>}
          <div className="new-issue-actions">
            <button type="submit" className="new-issue-button">Create issue</button>
            <button type="button" onClick={() => { setCreating(false); setError(''); }}>Cancel</button>
          </div>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

