  const [issueItems, setIssueItems] = useState(issues);
  const [isCreating, setIsCreating] = useState(false);
  const [title, setTitle] = useState('');
  const [titleError, setTitleError] = useState('');

  const visible = issueItems.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  function createIssue(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const cleanTitle = title.trim();
    if (!cleanTitle) {
      setTitleError('Title is required.');
      return;
    }

    const nextId = Math.max(...issueItems.map((issue) => issue.id), 0) + 1;
    setIssueItems([
      {
        id: nextId,
        title: cleanTitle,
        description: '',
        status: 'open',
        assignee: 'Unassigned',
        tags: [],
        createdAt: new Date().toISOString().slice(0, 10),
      },
      ...issueItems,
    ]);
    setTitle('');
    setTitleError('');
    setIsCreating(false);
    setStatus('all');
    setAssignee('all');
  }

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" onClick={() => { setIsCreating(!isCreating); setTitleError(''); }}>
          {isCreating ? 'Cancel' : 'New issue'}
