            autoFocus
            value={title}
            onChange={(event) => { setTitle(event.target.value); setTitleError(''); }}
            aria-invalid={Boolean(titleError)}
            aria-describedby={titleError ? 'new-issue-error' : undefined}
          />
          {titleError && <p id="new-issue-error" role="alert">{titleError}</p>}
          <button type="submit">Create issue</button>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issueItems.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

