import { FormEvent, useState } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [creating, setCreating] = useState(false);
  const [title, setTitle] = useState('');
  const [titleError, setTitleError] = useState('');

  function createIssue(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setTitleError('Title is required.');
      return;
    }
    issues.unshift({
      id: Math.max(0, ...issues.map((issue) => issue.id)) + 1,
      title: trimmedTitle,
      description: '',
      status: 'open',
      assignee: 'Unassigned',
      tags: [],
      createdAt: new Date().toISOString().slice(0, 10),
    });
    setTitle('');
    setTitleError('');
    setCreating(false);
  }

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" onClick={() => setCreating(!creating)}>New issue</button>
      </div>
      {creating && (
        <form className="new-issue-form" onSubmit={createIssue} noValidate>
          <label htmlFor="new-issue-title">Title</label>
          <input
            id="new-issue-title"
            value={title}
            onChange={(event) => {
              setTitle(event.target.value);
              if (titleError) setTitleError('');
            }}
            aria-invalid={Boolean(titleError)}
            aria-describedby={titleError ? 'new-issue-title-error' : undefined}
            autoFocus
          />
          {titleError && <p id="new-issue-title-error" role="alert">{titleError}</p>}
          <div className="new-issue-form__actions">
            <button type="submit">Create issue</button>
            <button type="button" onClick={() => setCreating(false)}>Cancel</button>
          </div>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

