import { useState } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { createIssue, issues } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [creating, setCreating] = useState(false);
  const [title, setTitle] = useState('');
  const [error, setError] = useState('');
  const [, refresh] = useState(0);

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  function submitIssue(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      setError('Title is required.');
      return;
    }
    createIssue(trimmedTitle);
    setTitle('');
    setError('');
    setCreating(false);
    refresh((value) => value + 1);
  }

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button type="button" onClick={() => { setCreating((value) => !value); setError(''); }}>
          {creating ? 'Cancel' : 'New issue'}
        </button>
      </div>
      {creating && (
        <form className="new-issue-form" onSubmit={submitIssue}>
          <label htmlFor="issue-title">Title</label>
          <input
            autoFocus
            id="issue-title"
            value={title}
            onChange={(event) => { setTitle(event.target.value); setError(''); }}
            aria-invalid={Boolean(error)}
            aria-describedby={error ? 'issue-title-error' : undefined}
          />
          {error && <p id="issue-title-error" className="form-error" role="alert">{error}</p>}
          <button type="submit">Create issue</button>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

