import { useState } from 'react';
import FilterBar from '../components/FilterBar';
import IssueCard from '../components/IssueCard';
import { issues } from '../data/issues';

export default function IssueList() {
  const [status, setStatus] = useState('all');
  const [assignee, setAssignee] = useState('all');
  const [showForm, setShowForm] = useState(false);
  const [title, setTitle] = useState('');
  const [titleError, setTitleError] = useState('');
  const [, refresh] = useState(0);

  const visible = issues.filter((issue) => {
    if (status !== 'all' && issue.status !== status) return false;
    if (assignee !== 'all' && issue.assignee !== assignee) return false;
    return true;
  });

  return (
    <section>
      <div className="issues-heading">
        <h1>Issues</h1>
        <button className="primary-button" type="button" onClick={() => { setShowForm(true); setTitleError(''); }}>
          New issue
        </button>
      </div>
      {showForm && (
        <form className="new-issue-form" onSubmit={(event) => {
          event.preventDefault();
          const cleanTitle = title.trim();
          if (!cleanTitle) {
            setTitleError('Title is required.');
            return;
          }
          issues.unshift({
            id: Math.max(...issues.map((issue) => issue.id), 0) + 1,
            title: cleanTitle,
            description: '',
            status: 'open',
            assignee: 'Unassigned',
            tags: [],
            createdAt: new Date().toISOString().slice(0, 10),
          });
          refresh((value) => value + 1);
          setTitle('');
          setTitleError('');
          setShowForm(false);
          setStatus('all');
          setAssignee('all');
        }}>
          <label htmlFor="new-issue-title">Title</label>
          <input
            id="new-issue-title"
            autoFocus
            value={title}
            onChange={(event) => { setTitle(event.target.value); if (titleError) setTitleError(''); }}
            aria-invalid={Boolean(titleError)}
            aria-describedby={titleError ? 'new-issue-title-error' : undefined}
          />
          {titleError && <p id="new-issue-title-error" className="form-error" role="alert">{titleError}</p>}
          <div className="new-issue-form__actions">
            <button className="primary-button" type="submit">Create issue</button>
            <button type="button" onClick={() => { setShowForm(false); setTitleError(''); }}>Cancel</button>
          </div>
        </form>
      )}
      <FilterBar
        status={status}
        assignee={assignee}
        onStatusChange={setStatus}
        onAssigneeChange={setAssignee}
      />
      <p className="result-count">
        {visible.length} of {issues.length} issues
      </p>
      <div className="issue-grid">
        {visible.map((issue) => (
          <IssueCard key={issue.id} issue={issue} />
        ))}
      </div>
    </section>
  );
}

